public class FileProcessor {
    public String processFile(String path) {
        String result = null;
        try {
            var content = Files.readString(Path.of(path));
            result = content.toUpperCase();
            System.out.println("Try block executed");
            return result;
        } catch (IOException e) {
            System.out.println("Catch block executed");
            result = "ERROR: " + e.getMessage();
            return result;
        } finally {
            System.out.println("Finally block always executes");
            // Cleanup code here runs regardless of return statements above
        }
    }

    // Scenario 1: No exception → Try runs, Finally runs
    // Scenario 2: IOException thrown → Try stops, Catch runs, Finally runs
    // Scenario 3: NullPointerException thrown → Try stops, no matching catch, Finally runs, exception propagates
}

public class LockManager {
    private final ReentrantLock lock = new ReentrantLock();

    public void performCriticalOperation() {
        lock.lock();  // Acquire the lock
        try {
            // Critical section code that might throw exceptions
            var data = fetchDataFromDatabase();
            processData(data);
            // We're not catching exceptions here - let them propagate
        } finally {
            lock.unlock();  // Always release the lock, no matter what
        }
        // If an exception occurred above, it propagates to our caller
    }

    // Another valid use case: cleanup with re-throw
    public void processFile(String path) throws IOException {
        var connection = openConnection();
        try {
            connection.sendData(Files.readAllBytes(Path.of(path)));
        } finally {
            connection.close();  // Guaranteed cleanup even if sendData throws
        }
    }
}

public class ReturnFinally {
    // BAD PRACTICE: Return in finally overrides try's return
    public int badExample() {
        try {
            return 10;  // This return is discarded!
        } finally {
            return 20;  // This return wins - method returns 20
        }
    }

    // WORSE: Return in finally swallows exceptions
    public String terribleExample() {
        try {
            throw new IOException("Critical error");
        } catch (IOException e) {
            throw new RuntimeException("Wrapped error", e);
        } finally {
            return "SUCCESS";  // Exception completely swallowed! Caller thinks success.
        }
    }

    // CORRECT: Finally does cleanup only, no return
    public int correctExample() {
        var resource = acquireResource();
        try {
            return processResource(resource);
        } finally {
            resource.close();  // Cleanup only, no return
        }
    }
}

public class OrderService {
    public void processOrder(String orderId) {
        try {
            var orderFile = Path.of("/orders/" + orderId + ".json");
            var content = Files.readString(orderFile);
            var order = parseJson(content);
            saveToDatabase(order);
        } catch (FileNotFoundException e) {
            // Most specific: handle missing file case
            System.err.println("Order file not found: " + orderId);
        } catch (IOException e) {
            // More general: handle other I/O errors like permission denied
            System.err.println("I/O error reading order: " + e.getMessage());
        } catch (JsonParseException e) {
            // Different hierarchy: JSON parsing errors
            System.err.println("Invalid order JSON format");
        } catch (Exception e) {
            // Most general: catch-all for unexpected errors
            System.err.println("Unexpected error: " + e.getMessage());
            throw new RuntimeException("Failed to process order", e);
        }
    }
}

public class OrderRepository {
    public Order findById(Long orderId) {
        Connection conn = null;
        try {
            conn = dataSource.getConnection();
            var stmt = conn.prepareStatement("SELECT * FROM orders WHERE id = ?");
            stmt.setLong(1, orderId);
            var rs = stmt.executeQuery();
            return mapToOrder(rs);
        } catch (SQLException e) {
            // Original SQLException caught here
            System.err.println("Database error: " + e.getMessage());
            // WRONG: Throws new exception, original is lost
            // throw new DataAccessException("Failed to find order");

            // CORRECT: Chain the original exception as the cause
            throw new DataAccessException("Failed to find order: " + orderId, e);
        } finally {
            if (conn != null) {
                conn.close();  // Finally runs even when catch throws
            }
        }
    }

    // Custom exception with cause chaining
    static class DataAccessException extends RuntimeException {
        public DataAccessException(String message, Throwable cause) {
            super(message, cause);  // Preserves original exception
        }
    }
}
